create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,full_name text not null,bio text default '',created_at timestamptz default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null,topic text not null default 'General',tags text[] not null default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz default now());
create table if not exists public.likes(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(post_id,user_id));
create table if not exists public.follows(follower_id uuid references public.profiles(id) on delete cascade,following_id uuid references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,following_id));
create table if not exists public.saved_posts(user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,post_id));
alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.comments enable row level security;alter table public.likes enable row level security;alter table public.follows enable row level security;alter table public.saved_posts enable row level security;
create policy if not exists profiles_read on public.profiles for select using(true);create policy if not exists profiles_insert on public.profiles for insert with check(auth.uid()=id);create policy if not exists profiles_update on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy if not exists posts_read on public.posts for select using(true);create policy if not exists posts_insert on public.posts for insert with check(auth.uid()=user_id);create policy if not exists posts_update on public.posts for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy if not exists posts_delete on public.posts for delete using(auth.uid()=user_id);
create policy if not exists comments_read on public.comments for select using(true);create policy if not exists comments_insert on public.comments for insert with check(auth.uid()=user_id);create policy if not exists comments_delete on public.comments for delete using(auth.uid()=user_id);
create policy if not exists likes_read on public.likes for select using(true);create policy if not exists likes_manage on public.likes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists follows_read on public.follows for select using(true);create policy if not exists follows_manage on public.follows for all using(auth.uid()=follower_id) with check(auth.uid()=follower_id);
create policy if not exists saved_private on public.saved_posts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
